import { useState } from 'react';
const initial={name:'',email:'',phone:'',role:'',message:''};
export default function ContactForm(){const [data,setData]=useState(initial),[errors,setErrors]=useState({}),[sent,setSent]=useState(false),[loading,setLoading]=useState(false);const update=e=>setData({...data,[e.target.name]:e.target.value});const submit=e=>{e.preventDefault();const next={};if(!data.name.trim())next.name='Enter your full name.';if(!/^\S+@\S+\.\S+$/.test(data.email))next.email='Enter a valid email address.';if(!data.role)next.role='Choose the option that best describes you.';if(!data.message.trim())next.message='Tell us a little about how we can help.';setErrors(next);if(Object.keys(next).length)return;setLoading(true);setTimeout(()=>{setLoading(false);setSent(true);setData(initial)},600)};return <form className="contact-form" noValidate onSubmit={submit}>{sent&&<div className="form-success" role="status">Thank you. Our team will be in touch shortly.</div>}<div className="row g-4"><Field label="Full Name" name="name" value={data.name} onChange={update} error={errors.name}/><Field label="Email Address" name="email" type="email" value={data.email} onChange={update} error={errors.email}/><Field label="Phone Number" name="phone" value={data.phone} onChange={update}/><div className="col-12 col-md-6"><label htmlFor="role">I am a...</label><select id="role" name="role" value={data.role} onChange={update} aria-invalid={!!errors.role} aria-describedby={errors.role?'role-error':undefined}><option value="">Select an option</option><option>Candidate</option><option>Employer</option><option>Partner</option><option>Other</option></select>{errors.role&&<small id="role-error">{errors.role}</small>}</div><div className="col-12"><label htmlFor="message">Message</label><textarea id="message" name="message" rows="5" value={data.message} onChange={update} placeholder="How can we help?" aria-invalid={!!errors.message} aria-describedby={errors.message?'message-error':undefined}/>{errors.message&&<small id="message-error">{errors.message}</small>}</div><div className="col-12"><button className="btn btn-primary" disabled={loading}>{loading?'Sending…':'Send Message'}<span>→</span></button></div></div></form>}
function Field({label,name,type='text',value,onChange,error}){return <div className="col-12 col-md-6"><label htmlFor={name}>{label}</label><input id={name} name={name} type={type} value={value} onChange={onChange} placeholder={label} aria-invalid={!!error} aria-describedby={error?`${name}-error`:undefined}/>{error&&<small id={`${name}-error`}>{error}</small>}</div>}
